type entry struct {
	value    []byte
	expiresAt time.Time
	hasExpiry bool
}

type store struct {
	mu   sync.RWMutex
	data map[string]entry
}

func newStore() *store {
	return &store{data: make(map[string]entry)}
}

func keyString(key []byte) string {
	return string(key)
}

func (s *store) get(key []byte) ([]byte, bool) {
	ks := keyString(key)
	now := time.Now()

	s.mu.RLock()
	e, ok := s.data[ks]
	if !ok {
		s.mu.RUnlock()
		return nil, false
	}
	if e.hasExpiry && !e.expiresAt.After(now) {
		s.mu.RUnlock()
		s.mu.Lock()
		e2, ok2 := s.data[ks]
		if ok2 && e2.hasExpiry && !e2.expiresAt.After(time.Now()) {
			delete(s.data, ks)
		}
		s.mu.Unlock()
		return nil, false
	}
	val := append([]byte(nil), e.value...)
	s.mu.RUnlock()
	return val, true
}

func (s *store) set(key, value []byte, ttl *time.Duration) {
	ks := keyString(key)
	v := append([]byte(nil), value...)
	e := entry{value: v}
	if ttl != nil {
		e.hasExpiry = true
		e.expiresAt = time.Now().Add(*ttl)
	}
	s.mu.Lock()
	s.data[ks] = e
	s.mu.Unlock()
}

func (s *store) del(keys [][]byte) int64 {
	now := time.Now()
	seen := make(map[string]struct{}, len(keys))
	var deleted int64
	s.mu.Lock()
	defer s.mu.Unlock()
	for _, key := range keys {
		ks := keyString(key)
		if _, ok := seen[ks]; ok {
			continue
		}
		seen[ks] = struct{}{}
		e, ok := s.data[ks]
		if !ok {
			continue
		}
		if e.hasExpiry && !e.expiresAt.After(now) {
			delete(s.data, ks)
			continue
		}
		delete(s.data, ks)
		deleted++
	}
	return deleted
}

type respConn struct {
	r *bufio.Reader
	w *bufio.Writer
}

func newRespConn(c net.Conn) *respConn {
	return &respConn{
		r: bufio.NewReader(c),
		w: bufio.NewWriter(c),
	}
}

func (c *respConn) readLine() ([]byte, error) {
	line, err := c.r.ReadBytes('\n')
	if err != nil {
		return nil, err
	}
	if len(line) < 2 || line[len(line)-2] != '\r' {
		return nil, errors.New("protocol error")
	}
	return line[:len(line)-2], nil
}

func (c *respConn) readRequest() ([][]byte, error) {
	line, err := c.readLine()
	if err != nil {
		return nil, err
	}
	if len(line) == 0 || line[0] != '*' {
		return nil, errors.New("protocol error")
	}
	n, err := strconv.Atoi(string(line[1:]))
	if err != nil || n < 0 {
		return nil, errors.New("protocol error")
	}
	args := make([][]byte, n)
	for i := 0; i < n; i++ {
		header, err := c.readLine()
		if err != nil {
			return nil, err
		}
		if len(header) == 0 || header[0] != '$' {
			return nil, errors.New("protocol error")
		}
		l, err := strconv.Atoi(string(header[1:]))
		if err != nil || l < 0 {
			return nil, errors.New("protocol error")
		}
		buf := make([]byte, l+2)
		if _, err := io.ReadFull(c.r, buf); err != nil {
			return nil, err
		}
		if buf[l] != '\r' || buf[l+1] != '\n' {
			return nil, errors.New("protocol error")
		}
		args[i] = append([]byte(nil), buf[:l]...)
	}
